import './style.css';
import {createWorld} from './world.js';

const key='field-atlas-v1';
let saved=null;try{saved=JSON.parse(localStorage.getItem(key));}catch{}
const defaults={rows:5,mechanical:60,confidence:75,protect:20,field:'01'};
let config={...defaults,...saved?.config},page='home',task=saved?.task||null,selected=null,world,preview=false,timer=null;
if(task?.status==='running')task.status='paused';
const fields={'01':'东侧试验田','02':'苗圃示范区'};
const $=s=>document.querySelector(s);
$('#app').innerHTML=`<header><a class="brand" href="#" aria-label="返回首页"><span class="brand-symbol">田</span><span>田野切片<small>FIELD ATLAS</small></span></a><nav><button data-page="home" class="active">总览</button><button data-page="plan">田块编排</button><button data-page="work">作业现场</button><button data-page="archive">任务档案</button></nav><div class="header-right"><span class="mode"><i></i> 模拟模式</span><button id="lab-button" class="text-button">设备实验台 ↗</button></div></header><main><section id="world"></section><div id="content"></div><div class="world-tools"><span>拖动旋转 · 滚轮缩放 · 点击杂草查看</span><button id="top-view">俯视</button><button id="iso-view">斜视</button><button id="robot-view">机器人近景</button></div><aside id="plant-detail" hidden></aside></main><footer><span><i class="dot"></i> 本地工作站 <b>LOCAL</b></span><span>RK3576 / USB CAMERA <em>未连接</em></span><span>八轮双机构 · 概念结构</span><span id="save-status">本地自动保存</span></footer><div id="toast" role="status"></div><dialog id="dialog"></dialog>`;
world=createWorld($('#world'),id=>{selected=id;showPlant();});
window.__world=world;
function persist(){try{localStorage.setItem(key,JSON.stringify({config,task}));$('#save-status').textContent='已保存至本机 · '+new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'});}catch{$('#save-status').textContent='存储不可用 · 请导出任务';}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('visible'),3000);}
function statusName(){return !task?'尚未开始':({running:'模拟运行中',paused:'已暂停',completed:'模拟已完成',cancelled:'已取消'})[task.status];}
function methodFor(id,c=config){const confidence=62+(id*13%37),distance=12+(id*7%40);if(confidence<c.confidence)return {method:'跳过',reason:'低于置信度阈值',confidence,distance};if(distance<c.protect)return {method:'跳过',reason:'进入幼苗保护范围',confidence,distance};return {method:(id*37%100)<c.mechanical?'机械':'喷施',reason:'按已授权的模拟分配规则',confidence,distance};}
function counters(){const a=task?.records||[];return ['机械','喷施','跳过'].map(m=>a.filter(r=>r.method===m).length);}
function render(){document.body.dataset.page=page;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#plant-detail').hidden=true;const content=$('#content');
 if(page==='home'){content.innerHTML=`<div class="hero"><div class="eyebrow">PRECISION IN EVERY LEAF <span>— 001</span></div><h1>让每一株幼苗，<br><em>被看见。</em></h1><p class="intro">在数字田野里，规划每一次精准作业。<br>从一片土地，到一株生命。</p><div class="hero-actions"><button class="primary" id="new-task">新建作业 <span>↗</span></button><button class="secondary" id="continue-task">${task?'查看当前任务':'探索田块'} →</button></div><div class="hero-caption"><span class="tiny-line"></span> EIGHT WHEELS. ONE LIVING FIELD.<br><small>八轮自适应底盘 / 视觉感知 / 双机构协同</small></div></div><div class="scene-caption"><span>01 / FIELD STUDY</span><h3>${fields[config.field]}</h3><p>示例田块 · 非真实测绘</p></div><div class="overview-strip"><div><label>设备连接</label><strong><i class="neutral-dot"></i> 等待硬件接入</strong></div><div><label>当前任务</label><strong>${statusName()}</strong></div><div><label>作业方式</label><strong>机械 + 定点喷施</strong></div><div><label>数据来源</label><strong>内置模拟场景 <span class="small-arrow">↗</span></strong></div></div>`;$('#new-task').onclick=()=>navigate('plan');$('#continue-task').onclick=()=>navigate(task?'work':'plan');}
 if(page==='plan'){content.innerHTML=`<div class="page-heading"><div class="eyebrow">FIELD COMPOSITION / 02</div><h2>编排一场<span>精准作业。</span></h2><p>整田路径与单株策略，在同一片田野中相遇。</p></div><div class="map-label"><b>LOCAL COORDINATES</b><span>11 × 8 m · 示例坐标 / 地形示意</span></div><section class="inspector"><div class="panel-top"><span>任务配置</span><b>01 — 03</b></div><label class="field-label">选择示例田块<select id="field"><option value="01">01 · 东侧试验田</option><option value="02">02 · 苗圃示范区</option></select></label><div class="section-label">01 / 覆盖路线</div>${range('rows','覆盖行数',3,8,config.rows,'行')}<div class="section-label">02 / 双机构模拟规则</div>${range('mechanical','机械分配比例',0,100,config.mechanical,'%')}<p class="hint">其余符合条件目标分配喷施。原型按目标编号确定分配，不代表农艺推荐。</p><div class="section-label">03 / 保护与复核</div>${range('confidence','最低置信度',60,99,config.confidence,'%')}${range('protect','幼苗保护距离',10,40,config.protect,'cm')}<p class="hint">距离、置信度均为模拟数据，冲突目标自动跳过。</p><button class="primary wide" id="preview">${preview?'重新生成预演':'生成作业预演'} <span>↗</span></button><button class="secondary wide" id="authorize" ${!preview?'disabled':''}>检查策略并授权</button><p class="panel-note">仅模拟 · 不发送硬件指令</p></section><div class="map-legend"><span class="route-swatch"></span>覆盖路线 <i class="swatch mechanical"></i>机械 <i class="swatch spray"></i>喷施 <i class="swatch skipped"></i>跳过</div>`;$('#field').value=config.field;$('#field').onchange=e=>{config.field=e.target.value;invalidate();};for(const id of ['rows','mechanical','confidence','protect'])$('#'+id).oninput=e=>{config[id]=Number(e.target.value);$('#'+id+'-value').textContent=config[id];invalidate();if(id==='rows')world.setRoute(config.rows);};$('#preview').onclick=()=>{preview=true;world.setRoute(config.rows);world.progress(0,world.targets.map(t=>({...t,...methodFor(t.id)})));render();toast('预演已生成 · 点击场景杂草查看分配依据');};$('#authorize').onclick=authorize;}
 if(page==='work'){const [m,s,k]=counters();content.innerHTML=`<div class="page-heading"><div class="eyebrow">LIVE SIMULATION / 03</div><h2>田野，<span>正在回应。</span></h2><p>${task?fields[task.config.field]+' · '+statusName():'尚无作业任务，请先配置策略并授权。'}</p></div><section class="inspector operation"><div class="panel-top"><span>模拟作业观察</span><b class="live-dot">● SIM</b></div><div class="synthetic-view" id="onboard-view"><span class="frame-corner">三维机载视角 / 非真实摄像头</span></div><div class="operation-metrics"><div><b id="mechanical-count">${m}</b><small>机械记录</small></div><div><b id="spray-count">${s}</b><small>喷施记录</small></div><div><b id="skip-count">${k}</b><small>跳过目标</small></div></div><div class="section-label">当前事件</div><p id="current-event" class="event-text">${lastEvent()}</p><div class="hint">模拟完成仅表示动作记录，不代表真实除草效果。真实视频与遥测尚未接入。</div><div class="operation-controls">${task&&['running','paused'].includes(task.status)?`<button id="toggle" class="primary wide">${task.status==='running'?'暂停模拟':'继续模拟'} <span>Ⅱ</span></button><button id="cancel" class="secondary wide">取消任务</button>`:`<button id="go-plan" class="primary wide">${task?'规划下一次作业':'前往配置策略'} ↗</button>`}</div></section><div class="timeline-panel"><div><span id="task-status">${statusName()}</span><b id="percent">${Math.round((task?.progress||0)*100)}%</b></div><div class="progress-track"><i id="progress-fill" style="width:${(task?.progress||0)*100}%"></i></div><div class="timeline-labels"><span>策略授权</span><span>沿途识别 / 规则执行</span><span>任务归档</span></div></div>`;if($('#toggle'))$('#toggle').onclick=()=>{task.status=task.status==='running'?'paused':'running';task.events.push({text:task.status==='running'?'继续模拟':'人工暂停',at:task.progress});persist();render();};if($('#cancel'))$('#cancel').onclick=()=>{openDialog('<h2>取消当前模拟任务？</h2><p>已产生的动作记录将保留，任务不再继续执行。</p><button id="confirm-cancel" class="primary">确认取消</button><button class="secondary" data-close>返回</button>');$('#confirm-cancel').onclick=()=>{task.status='cancelled';task.events.push({text:'任务已取消',at:task.progress});persist();$('#dialog').close();render();};};if($('#go-plan'))$('#go-plan').onclick=()=>navigate('plan');}
 if(page==='archive'){content.innerHTML=`<div class="page-heading"><div class="eyebrow">FIELD MEMORY / 04</div><h2>每次经过，<span>都有迹可循。</span></h2><p>回看同一份任务记录，而非重新生成一次演示。</p></div><section class="archive-panel"><div class="panel-top"><span>当前保存任务</span><b>LOCAL RECORD</b></div>${task?`<h3>${fields[task.config.field]} <span class="tag">模拟数据</span></h3><p>${new Date(task.created).toLocaleString('zh-CN')} · ${statusName()}</p><label class="field-label">回放进度 <output id="replay-label">${Math.round(task.progress*100)}%</output><input type="range" id="replay" min="0" max="${task.progress}" step="0.001" value="${task.progress}"></label><div class="record-summary">${task.records.length} 条目标记录 · ${task.events.length} 条事件</div><div class="event-list">${task.events.slice().reverse().map(e=>`<div><span>${Math.round(e.at*100)}%</span>${e.text}</div>`).join('')}</div><button id="export" class="primary wide">导出模拟任务 JSON ↗</button><p class="hint">原型保留最近一次任务；新任务覆盖前会要求确认。完整多任务档案后续扩展。</p>`:'<div class="empty-state">还没有田野记忆。<br><small>完成一次策略授权，开始记录。</small></div><button id="archive-plan" class="primary wide">创建第一个任务 ↗</button>'}</section>`;if($('#replay'))$('#replay').oninput=e=>{const p=Number(e.target.value);$('#replay-label').textContent=Math.round(p*100)+'%';world.progress(p,task.records.filter(r=>r.at<=p));};if($('#export'))$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({source:'simulation',...task},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='field-atlas-simulation.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};if($('#archive-plan'))$('#archive-plan').onclick=()=>navigate('plan');}
 world.mountCamera(page==='work'?$('#onboard-view'):null);
 world.setRunning(task?.status==='running'&&page==='work');}
function range(id,label,min,max,value,unit){return `<label class="range-label">${label}<span><output id="${id}-value">${value}</output> ${unit}</span><input id="${id}" type="range" min="${min}" max="${max}" value="${value}"></label>`;}
function invalidate(){preview=false;world.progress(0,[]);$('#authorize').disabled=true;persist();}
function openDialog(html){$('#dialog').innerHTML=html+'<button class="dialog-close" data-close aria-label="关闭">×</button>';$('#dialog').querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#dialog').close());$('#dialog').showModal();}
function authorize(){if(task?.status==='running'){toast('请先暂停或完成当前任务');return;}const records=world.targets.map(t=>methodFor(t.id));openDialog(`<div class="eyebrow">SIMULATION AUTHORIZATION</div><h2>确认这一次作业。</h2><p>${fields[config.field]} · ${config.rows} 行覆盖路线</p><div class="authorization-grid"><div>机械分配<strong>${config.mechanical}%</strong></div><div>保护距离<strong>${config.protect} cm</strong></div><div>最低置信度<strong>${config.confidence}%</strong></div><div>预期跳过<strong>${records.filter(r=>r.method==='跳过').length} 株</strong></div></div><p class="hint">所有目标、定位与执行结果均为模拟。无硬件连接，不发送任何真实控制指令。${task?'开始新任务将覆盖本机最近任务，请先在档案中导出需要保留的记录。':''}</p><label class="consent"><input type="checkbox" id="consent"> 我已检查策略，同意开始模拟${task?'并替换当前记录':''}</label><button class="primary wide" id="start" disabled>开始模拟作业 ↗</button>`);$('#consent').onchange=e=>$('#start').disabled=!e.target.checked;$('#start').onclick=()=>{task={created:Date.now(),status:'running',progress:0,config:{...config},records:[],events:[{text:'模拟策略已授权',at:0}]};$('#dialog').close();persist();navigate('work');};}
function navigate(next){if(task?.status==='running'&&next!=='work'){task.status='paused';task.events.push({text:'离开作业页面，模拟自动暂停',at:task.progress});persist();toast('模拟已暂停，返回作业现场可继续');}page=next;render();world.setRoute((next==='work'||next==='archive')&&task?task.config.rows:config.rows);world.view(next==='plan'?'plan':next==='home'?'home':'work');if(next!=='home')world.progress(task&&(next==='work'||next==='archive')?task.progress:0,task&&(next==='work'||next==='archive')?task.records:[]);}
function lastEvent(){return task?.events.at(-1)?.text||'等待策略授权';}
function showPlant(){const rule=methodFor(selected,task&&page==='work'?task.config:config);$('#plant-detail').hidden=false;$('#plant-detail').innerHTML=`<button id="close-plant" aria-label="关闭目标详情">×</button><span class="eyebrow">TARGET ${String(selected+1).padStart(3,'0')} / 模拟</span><h3>杂草观察档案</h3><p>模拟置信度 <b>${rule.confidence}%</b></p><p>模拟最近幼苗距离 <b>${rule.distance} cm</b></p><p>策略分配 <b>${rule.method}</b></p><small>${rule.reason}。不是实测坐标或模型推理结果。</small>`;$('#close-plant').onclick=()=>$('#plant-detail').hidden=true;}
$('nav').onclick=e=>{const b=e.target.closest('[data-page]');if(b)navigate(b.dataset.page);};$('.brand').onclick=e=>{e.preventDefault();navigate('home');};$('#top-view').onclick=()=>world.view('plan');$('#iso-view').onclick=()=>world.view(page==='home'?'home':'work');$('#lab-button').onclick=()=>openDialog(`<div class="eyebrow">DEVICE LAB / CONNECTION BOUNDARY</div><h2>设备实验台</h2><div class="device-row">RK3576 <span>未连接</span></div><div class="device-row">USB 摄像头 <span>未接入</span></div><div class="device-row">YOLO / RKNN <span>模型服务未接入</span></div><div class="device-row">定位 / 标定 <span>未配置</span></div><div class="device-row">机械 / 喷施执行器 <span>未连接</span></div><p class="hint">当前为交互原型，不提供真实设备控制、图片推理或相机标定。三维模型为程序化概念模型，非 Blender 工程定稿。</p><button class="primary wide" data-close>返回工作站</button>`);
let last=performance.now();setInterval(()=>{const now=performance.now(),dt=Math.min((now-last)/1000,.5);last=now;if(task?.status!=='running')return;task.progress=Math.min(1,task.progress+dt/75);const count=Math.floor(task.progress*24);while(task.records.length<count){const id=task.records.length,rule=methodFor(id,task.config);task.records.push({id,...rule,at:(id+1)/24});task.events.push({text:`目标 ${String(id+1).padStart(3,'0')} · ${rule.method==='跳过'?'跳过：'+rule.reason:rule.method+'模拟动作已记录'}`,at:(id+1)/24});persist();}world.progress(task.progress,task.records);if(page==='work'){const counts=counters();$('#percent').textContent=Math.round(task.progress*100)+'%';$('#progress-fill').style.width=task.progress*100+'%';$('#current-event').textContent=lastEvent();['mechanical-count','spray-count','skip-count'].forEach((id,i)=>$('#'+id).textContent=counts[i]);}if(task.progress===1){task.status='completed';task.events.push({text:'模拟结束 · 未验证真实除草效果',at:1});persist();render();toast('模拟任务已完成，可在任务档案中回放');}},100);
document.addEventListener('visibilitychange',()=>{if(document.hidden&&task?.status==='running'){task.status='paused';task.events.push({text:'窗口隐藏，模拟自动暂停',at:task.progress});persist();render();}});
window.addEventListener('pagehide',persist);
$('#robot-view').onclick=()=>world.view('robot');
navigate('home');